10	/**
11	 * Adaptation of work of Kevin Lindsey(kevin@kevlindev.com)
12	 */
13	export class Point implements XY {
14	  declare x: number;
15	
16	  declare y: number;
17	
18	  constructor();
19	  constructor(x: number, y: number);
20	  constructor(point?: XY);
21	  constructor(arg0: number | XY = 0, y = 0) {
22	    if (typeof arg0 === 'object') {
23	      this.x = arg0.x;
24	      this.y = arg0.y;
25	    } else {
26	      this.x = arg0;
27	      this.y = y;
28	    }
29	  }
30	
31	  /**
32	   * Adds another point to this one and returns a new one with the sum
33	   * @param {XY} that
34	   * @return {Point} new Point instance with added values
35	   */
36	  add(that: XY): Point {
37	    return new Point(this.x + that.x, this.y + that.y);
38	  }
39	
40	  /**
41	   * Adds another point to this one
42	   * @param {XY} that
43	   * @return {Point} thisArg
44	   * @deprecated
45	   */
46	  addEquals(that: XY): Point {
47	    this.x += that.x;
48	    this.y += that.y;
49	    return this;
50	  }
51	
52	  /**
53	   * Adds value to this point and returns a new one
54	   * @param {Number} scalar
55	   * @return {Point} new Point with added value
56	   */
57	  scalarAdd(scalar: number): Point {
58	    return new Point(this.x + scalar, this.y + scalar);
59	  }
60	
61	  /**
62	   * Adds value to this point
63	   * @param {Number} scalar
64	   * @return {Point} thisArg
65	   * @deprecated
66	   */
67	  scalarAddEquals(scalar: number): Point {
68	    this.x += scalar;
69	    this.y += scalar;
70	    return this;
71	  }
72	
73	  /**
74	   * Subtracts another point from this point and returns a new one
75	   * @param {XY} that
76	   * @return {Point} new Point object with subtracted values
77	   */
78	  subtract(that: XY): Point {
79	    return new Point(this.x - that.x, this.y - that.y);
80	  }
81	
82	  /**
83	   * Subtracts another point from this point
84	   * @param {XY} that
85	   * @return {Point} thisArg
86	   * @deprecated
87	   */
88	  subtractEquals(that: XY): Point {
89	    this.x -= that.x;
90	    this.y -= that.y;
91	    return this;
92	  }
93	
94	  /**
95	   * Subtracts value from this point and returns a new one
96	   * @param {Number} scalar
97	   * @return {Point}
98	   */
99	  scalarSubtract(scalar: number): Point {
100	    return new Point(this.x - scalar, this.y - scalar);
101	  }
102	
103	  /**
104	   * Subtracts value from this point
105	   * @param {Number} scalar
106	   * @return {Point} thisArg
107	   * @deprecated
108	   */
109	  scalarSubtractEquals(scalar: number): Point {
110	    this.x -= scalar;
111	    this.y -= scalar;
112	    return this;
113	  }
114	
115	  /**
116	   * Multiplies this point by another value and returns a new one
117	   * @param {XY} that
118	   * @return {Point}
119	   */
120	  multiply(that: XY): Point {
121	    return new Point(this.x * that.x, this.y * that.y);
122	  }
123	
124	  /**
125	   * Multiplies this point by a value and returns a new one
126	   * @param {Number} scalar
127	   * @return {Point}
128	   */
129	  scalarMultiply(scalar: number): Point {
130	    return new Point(this.x * scalar, this.y * scalar);
131	  }
132	
133	  /**
134	   * Multiplies this point by a value
135	   * @param {Number} scalar
136	   * @return {Point} thisArg
137	   * @deprecated
138	   */
139	  scalarMultiplyEquals(scalar: number): Point {
140	    this.x *= scalar;
141	    this.y *= scalar;
142	    return this;
143	  }
144	
145	  /**
146	   * Divides this point by another and returns a new one
147	   * @param {XY} that
148	   * @return {Point}
149	   */
150	  divide(that: XY): Point {
151	    return new Point(this.x / that.x, this.y / that.y);
152	  }
153	
154	  /**
155	   * Divides this point by a value and returns a new one
156	   * @param {Number} scalar
157	   * @return {Point}
158	   */
159	  scalarDivide(scalar: number): Point {
160	    return new Point(this.x / scalar, this.y / scalar);
161	  }
162	
163	  /**
164	   * Divides this point by a value
165	   * @param {Number} scalar
166	   * @return {Point} thisArg
167	   * @deprecated
168	   */
169	  scalarDivideEquals(scalar: number): Point {
170	    this.x /= scalar;
171	    this.y /= scalar;
172	    return this;
173	  }
174	
175	  /**
176	   * Returns true if this point is equal to another one
177	   * @param {XY} that
178	   * @return {Boolean}
179	   */
180	  eq(that: XY): boolean {
181	    return this.x === that.x && this.y === that.y;
182	  }
183	
184	  /**
185	   * Returns true if this point is less than another one
186	   * @param {XY} that
187	   * @return {Boolean}
188	   */
189	  lt(that: XY): boolean {
190	    return this.x < that.x && this.y < that.y;
191	  }
192	
193	  /**
194	   * Returns true if this point is less than or equal to another one
195	   * @param {XY} that
196	   * @return {Boolean}
197	   */
198	  lte(that: XY): boolean {
199	    return this.x <= that.x && this.y <= that.y;
200	  }
201	
202	  /**
203	
204	   * Returns true if this point is greater another one
205	   * @param {XY} that
206	   * @return {Boolean}
207	   */
208	  gt(that: XY): boolean {
209	    return this.x > that.x && this.y > that.y;
210	  }
211	
212	  /**
213	   * Returns true if this point is greater than or equal to another one
214	   * @param {XY} that
215	   * @return {Boolean}
216	   */
217	  gte(that: XY): boolean {
218	    return this.x >= that.x && this.y >= that.y;
219	  }
220	
221	  /**
222	   * Returns new point which is the result of linear interpolation with this one and another one
223	   * @param {XY} that
224	   * @param {Number} t , position of interpolation, between 0 and 1 default 0.5
225	   * @return {Point}
226	   */
227	  lerp(that: XY, t = 0.5): Point {
228	    t = Math.max(Math.min(1, t), 0);
229	    return new Point(
230	      this.x + (that.x - this.x) * t,
231	      this.y + (that.y - this.y) * t,
232	    );
233	  }
234	
235	  /**
236	   * Returns distance from this point and another one
237	   * @param {XY} that
238	   * @return {Number}
239	   */
240	  distanceFrom(that: XY): number {
241	    const dx = this.x - that.x,
242	      dy = this.y - that.y;
243	    return Math.sqrt(dx * dx + dy * dy);
244	  }
245	
246	  /**
247	   * Returns the point between this point and another one
248	   * @param {XY} that
249	   * @return {Point}
250	   */
251	  midPointFrom(that: XY): Point {
252	    return this.lerp(that);
253	  }
254	
255	  /**
256	   * Returns a new point which is the min of this and another one
257	   * @param {XY} that
258	   * @return {Point}
259	   */
260	  min(that: XY): Point {
261	    return new Point(Math.min(this.x, that.x), Math.min(this.y, that.y));
262	  }
263	
264	  /**
265	   * Returns a new point which is the max of this and another one
266	   * @param {XY} that
267	   * @return {Point}
268	   */
269	  max(that: XY): Point {
270	    return new Point(Math.max(this.x, that.x), Math.max(this.y, that.y));
271	  }
272	
273	  /**
274	   * Returns string representation of this point
275	   * @return {String}
276	   */
277	  toString(): string {
278	    return `${this.x},${this.y}`;
279	  }
280	
281	  /**
282	   * Sets x/y of this point
283	   * @param {Number} x
284	   * @param {Number} y
285	   */
286	  setXY(x: number, y: number) {
287	    this.x = x;
288	    this.y = y;
289	    return this;
290	  }
291	
292	  /**
293	   * Sets x of this point
294	   * @param {Number} x
295	   */
296	  setX(x: number) {
297	    this.x = x;
298	    return this;
299	  }
300	
301	  /**
302	   * Sets y of this point
303	   * @param {Number} y
304	   */
305	  setY(y: number) {
306	    this.y = y;
307	    return this;
308	  }
309	
310	  /**
311	   * Sets x/y of this point from another point
312	   * @param {XY} that
313	   */
314	  setFromPoint(that: XY) {
315	    this.x = that.x;
316	    this.y = that.y;
317	    return this;
318	  }
319	
320	  /**
321	   * Swaps x/y of this point and another point
322	   * @param {XY} that
323	   */
324	  swap(that: XY) {
325	    const x = this.x,
326	      y = this.y;
327	    this.x = that.x;
328	    this.y = that.y;
329	    that.x = x;
330	    that.y = y;
331	  }
332	
333	  /**
334	   * return a cloned instance of the point
335	   * @return {Point}
336	   */
337	  clone(): Point {
338	    return new Point(this.x, this.y);
339	  }
340	
341	  /**
342	   * Rotates `point` around `origin` with `radians`
343	   * @param {XY} origin The origin of the rotation
344	   * @param {TRadian} radians The radians of the angle for the rotation
345	   * @return {Point} The new rotated point
346	   */
347	  rotate(radians: TRadian, origin: XY = ZERO): Point {
348	    // TODO benchmark and verify the add and subtract how much cost
349	    // and then in case early return if no origin is passed
350	    const sinus = sin(radians),
351	      cosinus = cos(radians);
352	    const p = this.subtract(origin);
353	    const rotated = new Point(
354	      p.x * cosinus - p.y * sinus,
355	      p.x * sinus + p.y * cosinus,
356	    );
357	    return rotated.add(origin);
358	  }
359	
360	  /**
361	   * Apply transform t to point p
362	   * @param  {TMat2D} t The transform
363	   * @param  {Boolean} [ignoreOffset] Indicates that the offset should not be applied
364	   * @return {Point} The transformed point
365	   */
366	  transform(t: TMat2D, ignoreOffset = false): Point {
367	    return new Point(
368	      t[0] * this.x + t[2] * this.y + (ignoreOffset ? 0 : t[4]),
369	      t[1] * this.x + t[3] * this.y + (ignoreOffset ? 0 : t[5]),
370	    );
371	  }
372	}
373	
374	export const ZERO = new Point(0, 0);
