1	import { reNewline } from '../../constants';
2	import type {
3	  TextStyle,
4	  TextStyleDeclaration,
5	} from '../../shapes/Text/StyledText';
6	import { cloneStyles } from '../internals/cloneStyles';
7	import { graphemeSplit } from '../lang_string';
8	
9	export type TextStyleArray = {
10	  start: number;
11	  end: number;
12	  style: TextStyleDeclaration;
13	}[];
14	
15	/**
16	 * @param {Object} prevStyle first style to compare
17	 * @param {Object} thisStyle second style to compare
18	 * @param {boolean} forTextSpans whether to check overline, underline, and line-through properties
19	 * @return {boolean} true if the style changed
20	 */
21	export const hasStyleChanged = (
22	  prevStyle: TextStyleDeclaration,
23	  thisStyle: TextStyleDeclaration,
24	  forTextSpans = false,
25	) =>
26	  prevStyle.fill !== thisStyle.fill ||
27	  prevStyle.stroke !== thisStyle.stroke ||
28	  prevStyle.strokeWidth !== thisStyle.strokeWidth ||
29	  prevStyle.fontSize !== thisStyle.fontSize ||
30	  prevStyle.fontFamily !== thisStyle.fontFamily ||
31	  prevStyle.fontWeight !== thisStyle.fontWeight ||
32	  prevStyle.fontStyle !== thisStyle.fontStyle ||
33	  prevStyle.textDecorationThickness !== thisStyle.textDecorationThickness ||
34	  prevStyle.textBackgroundColor !== thisStyle.textBackgroundColor ||
35	  prevStyle.deltaY !== thisStyle.deltaY ||
36	  (forTextSpans &&
37	    (prevStyle.overline !== thisStyle.overline ||
38	      prevStyle.underline !== thisStyle.underline ||
39	      prevStyle.linethrough !== thisStyle.linethrough));
40	
41	/**
42	 * Returns the array form of a text object's inline styles property with styles grouped in ranges
43	 * rather than per character. This format is less verbose, and is better suited for storage
44	 * so it is used in serialization (not during runtime).
45	 * @param {object} styles per character styles for a text object
46	 * @param {String} text the text string that the styles are applied to
47	 * @return {{start: number, end: number, style: object}[]}
48	 */
49	export const stylesToArray = (
50	  styles: TextStyle,
51	  text: string,
52	): TextStyleArray => {
53	  const textLines = text.split('\n'),
54	    stylesArray = [];
55	  let charIndex = -1,
56	    prevStyle = {};
57	  // clone style structure to prevent mutation
58	  styles = cloneStyles(styles);
59	
60	  //loop through each textLine
61	  for (let i = 0; i < textLines.length; i++) {
62	    const chars = graphemeSplit(textLines[i]);
63	    if (!styles[i]) {
64	      //no styles exist for this line, so add the line's length to the charIndex total and reset prevStyle
65	      charIndex += chars.length;
66	      prevStyle = {};
67	      continue;
68	    }
69	    //loop through each character of the current line
70	    for (let c = 0; c < chars.length; c++) {
71	      charIndex++;
72	      const thisStyle = styles[i][c];
73	      //check if style exists for this character
74	      if (thisStyle && Object.keys(thisStyle).length > 0) {
75	        if (hasStyleChanged(prevStyle, thisStyle, true)) {
76	          stylesArray.push({
77	            start: charIndex,
78	            end: charIndex + 1,
79	            style: thisStyle,
80	          });
81	        } else {
82	          //if style is the same as previous character, increase end index
83	          stylesArray[stylesArray.length - 1].end++;
84	        }
85	      }
86	      prevStyle = thisStyle || {};
87	    }
88	  }
89	  return stylesArray;
90	};
91	
92	/**
93	 * Returns the object form of the styles property with styles that are assigned per
94	 * character rather than grouped by range. This format is more verbose, and is
95	 * only used during runtime (not for serialization/storage)
96	 * @param {Array} styles the serialized form of a text object's styles
97	 * @param {String} text the text string that the styles are applied to
98	 * @return {Object}
99	 */
100	export const stylesFromArray = (
101	  styles: TextStyleArray | TextStyle,
102	  text: string,
103	): TextStyle => {
104	  if (!Array.isArray(styles)) {
105	    // clone to prevent mutation
106	    return cloneStyles(styles);
107	  }
108	  const textLines = text.split(reNewline),
109	    stylesObject: TextStyle = {};
110	  let charIndex = -1,
111	    styleIndex = 0;
112	  //loop through each textLine
113	  for (let i = 0; i < textLines.length; i++) {
114	    const chars = graphemeSplit(textLines[i]);
115	
116	    //loop through each character of the current line
117	    for (let c = 0; c < chars.length; c++) {
118	      charIndex++;
119	      //check if there's a style collection that includes the current character
120	      if (
121	        styles[styleIndex] &&
122	        styles[styleIndex].start <= charIndex &&
123	        charIndex < styles[styleIndex].end
124	      ) {
125	        //create object for line index if it doesn't exist
126	        stylesObject[i] = stylesObject[i] || {};
127	        //assign a style at this character's index
128	        stylesObject[i][c] = { ...styles[styleIndex].style };
129	        //if character is at the end of the current style collection, move to the next
130	        if (charIndex === styles[styleIndex].end - 1) {
131	          styleIndex++;
132	        }
133	      }
134	    }
135	  }
136	  return stylesObject;
137	};
