1	/**
2	 * Populates an object with properties of another object
3	 * @param {Object} source Source object
4	 * @param {string[]} properties Properties names to include
5	 * @returns object populated with the picked keys
6	 */
7	export const pick = <T extends Record<string, any>>(
8	  source: T,
9	  keys: (keyof T)[] = [],
10	) => {
11	  return keys.reduce((o, key) => {
12	    if (key in source) {
13	      o[key] = source[key];
14	    }
15	    return o;
16	  }, {} as Partial<T>);
17	};
18	
19	export const pickBy = <T extends Record<string, any>>(
20	  source: T,
21	  predicate: <K extends keyof T>(value: T[K], key: K, collection: T) => boolean,
22	) => {
23	  return (Object.keys(source) as (keyof T)[]).reduce((o, key) => {
24	    if (predicate(source[key], key, source)) {
25	      o[key] = source[key];
26	    }
27	    return o;
28	  }, {} as Partial<T>);
29	};
