257	      center = this.getCenterPoint(),
258	      tMatrix = createTranslateMatrix(center.x, center.y),
259	      rMatrix = createRotateMatrix({
260	        angle: this.getTotalAngle() - (!!this.group && this.flipX ? 180 : 0),
261	      }),
262	      positionMatrix = multiplyTransformMatrices(tMatrix, rMatrix),
263	      startMatrix = multiplyTransformMatrices(vpt, positionMatrix),
264	      finalMatrix = multiplyTransformMatrices(startMatrix, [
265	        1 / vpt[0],
266	        0,
267	        0,
268	        1 / vpt[3],
269	        0,
270	        0,
271	      ]),
272	      transformOptions = this.group
273	        ? qrDecompose(this.calcTransformMatrix())
274	        : undefined;
